using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
namespace Society.Api;
public record MfaPassword(string Password);
public record MfaCode(string Code,bool Recovery=false);
public record MfaDisable(string Password,string Code);
public static class SecurityCenter {
 public static readonly string[] HighRisk=["roles.manage","settings.manage","branding.manage","studio.publish","studio.issue","studio.approve","studio.bulk","studio.settings","finance.configure","finance.collect","finance.approve","finance.refund","finance.providers","finance.periods","finance.highvalue","reports.schedule"];
 public static async Task Strong(Access a,AppDb db,IHttpContextAccessor accessor){var context=accessor.HttpContext;if(context?.User.Identity?.AuthenticationType=="FinanceWorker")return;var env=context?.RequestServices.GetService<IHostEnvironment>();if(env==null||!env.IsProduction())return;var mfa=context!.User.FindFirstValue("amr")=="mfa";var recent=long.TryParse(context.User.FindFirstValue("mfa_at"),out var time)&&time>DateTimeOffset.UtcNow.AddMinutes(-30).ToUnixTimeSeconds();if(!mfa||!recent||!await db.Users.AnyAsync(u=>u.Id==a.UserId&&u.TwoFactorEnabled))throw new AccessDeniedException();}
 static Claim[] Claims()=>[new("amr","mfa"),new("mfa_at",DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString())];
 public static void Map(RouteGroupBuilder api){
  api.MapPost("/auth/two-factor",async(MfaCode r,UserManager<Account> users,SignInManager<Account> signIn)=>{var user=await signIn.GetTwoFactorAuthenticationUserAsync();if(user==null)return Results.Problem(statusCode:401,title:"Start a new sign-in before entering a verification code");var result=r.Recovery?await signIn.TwoFactorRecoveryCodeSignInAsync(r.Code):await signIn.TwoFactorAuthenticatorSignInAsync(r.Code.Replace(" ","").Replace("-",""),false,false);if(!result.Succeeded)return Results.Problem(statusCode:401,title:"Verification failed or account locked");await signIn.SignInWithClaimsAsync(user,false,Claims());return Results.Ok(new{message="Signed in with MFA"});}).RequireRateLimiting("auth");
  var t=api.MapGroup("/security").RequireAuthorization().RequireRateLimiting("auth");
  t.MapGet("/status",async(Access a,AppDb db,HttpContext context,IHostEnvironment env)=>new{mfaEnabled=await db.Users.Where(u=>u.Id==a.UserId).Select(u=>u.TwoFactorEnabled).SingleAsync(),mfaSession=context.User.FindFirstValue("amr")=="mfa",highRiskMfaRequired=env.IsProduction(),highRiskPermissions=HighRisk,sessionPolicy="HttpOnly SameSite Strict session cookie; 8-hour lifetime; production high-risk operations require MFA within 30 minutes"});
  t.MapPost("/mfa/setup",async(MfaPassword r,Access a,UserManager<Account> users)=>{var user=(await users.FindByIdAsync(a.UserId.ToString()))!;if(user.TwoFactorEnabled)throw new DomainException("MFA is already enabled; use your authenticator or recovery code to sign in");if(!await users.CheckPasswordAsync(user,r.Password))throw new AccessDeniedException();await users.ResetAuthenticatorKeyAsync(user);var key=await users.GetAuthenticatorKeyAsync(user);return Results.Ok(new{key,authenticatorUri="otpauth://totp/Assemblia:"+Uri.EscapeDataString(user.Email!)+"?secret="+key+"&issuer=Assemblia&digits=6"});});
  t.MapPost("/mfa/enable",async(MfaCode r,Access a,UserManager<Account> users,SignInManager<Account> signIn)=>{var user=(await users.FindByIdAsync(a.UserId.ToString()))!;if(user.TwoFactorEnabled)throw new DomainException("MFA is already enabled");if(!await users.VerifyTwoFactorTokenAsync(user,users.Options.Tokens.AuthenticatorTokenProvider,r.Code.Replace(" ","")))throw new DomainException("Authenticator code is invalid");await users.SetTwoFactorEnabledAsync(user,true);var recovery=(await users.GenerateNewTwoFactorRecoveryCodesAsync(user,10))!.ToArray();await signIn.SignInWithClaimsAsync(user,false,Claims());return Results.Ok(new{recoveryCodes=recovery,message="Store these recovery codes securely; they are returned only now"});});
  t.MapPost("/mfa/disable",async(MfaDisable r,Access a,UserManager<Account> users,SignInManager<Account> signIn)=>{var user=(await users.FindByIdAsync(a.UserId.ToString()))!;if(!await users.CheckPasswordAsync(user,r.Password)||!await users.VerifyTwoFactorTokenAsync(user,users.Options.Tokens.AuthenticatorTokenProvider,r.Code.Replace(" ","")))throw new AccessDeniedException();await users.SetTwoFactorEnabledAsync(user,false);await users.ResetAuthenticatorKeyAsync(user);await users.UpdateSecurityStampAsync(user);await signIn.SignOutAsync();return Results.Ok(new{message="MFA disabled and this session ended. High-risk production actions require MFA to be enabled again."});});
 }
}
